using Armelle.Data;
using Armelle.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
namespace Armelle.Controllers;
public class PromotionsController(ClinicDb db):Controller {
 bool Owner => HttpContext.Session.GetString("Role")=="Owner" && !string.IsNullOrEmpty(HttpContext.Session.GetString("User"));
 public async Task<IActionResult> Index() {if(!Owner)return RedirectToAction("Login","Auth");ViewBag.History=await db.PromotionAudits.OrderByDescending(x=>x.AtUtc).Take(150).ToListAsync();ViewBag.Redemptions=await db.PromotionRedemptions.OrderByDescending(x=>x.RedeemedAtUtc).Take(150).ToListAsync();return View(await db.ClinicPromotions.OrderByDescending(x=>x.CreatedAt).ToListAsync());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Save(int id,string title,string description,string promoCode,string discountType,decimal discountValue,DateTime startsAt,DateTime endsAt,bool isPublished=false) {if(!Owner)return Forbid();if(string.IsNullOrWhiteSpace(title)||title.Length>120||description?.Length>1000||promoCode?.Length>50||endsAt.Date<startsAt.Date||discountValue<0||!new[]{"Percent","Amount"}.Contains(discountType)||discountType=="Percent"&&discountValue>100)return BadRequest("Invalid promotion information.");var item=id==0?new ClinicPromotion():await db.ClinicPromotions.FindAsync(id);if(item==null)return NotFound();if(id==0){item.CreatedBy=HttpContext.Session.GetString("User")!;db.ClinicPromotions.Add(item);}item.Title=title.Trim();item.Description=(description??"").Trim();item.PromoCode=(promoCode??"").Trim();item.DiscountType=discountType;item.DiscountValue=discountValue;item.StartsAt=startsAt.Date;item.EndsAt=endsAt.Date;item.IsPublished=isPublished;await db.SaveChangesAsync();db.PromotionAudits.Add(new PromotionAudit{PromotionId=item.Id,Action=id==0?"Created":"Updated",OwnerUsername=HttpContext.Session.GetString("User")!,Details=$"{item.Title} | Published: {isPublished}"});await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SetPublished(int id,bool published){if(!Owner)return Forbid();var p=await db.ClinicPromotions.FindAsync(id);if(p==null)return NotFound();p.IsPublished=published;db.PromotionAudits.Add(new PromotionAudit{PromotionId=id,Action=published?"Published":"Unpublished",OwnerUsername=HttpContext.Session.GetString("User")!,Details=p.Title});await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> RecordRedemption(int promotionId,int patientUserId,string? reference){if(!Owner)return Forbid();var promo=await db.ClinicPromotions.FindAsync(promotionId);var patient=await db.AppUsers.FirstOrDefaultAsync(x=>x.Id==patientUserId&&x.Role=="Patient");if(promo==null||patient==null||!promo.IsPublished||promo.StartsAt.Date>DateTime.Today||promo.EndsAt.Date<DateTime.Today)return BadRequest("Promotion or patient is not eligible.");if(await db.PromotionRedemptions.AnyAsync(x=>x.PromotionId==promotionId&&x.PatientUserId==patientUserId&&x.Reference==(reference??"")))return BadRequest("This redemption is already recorded.");db.PromotionRedemptions.Add(new PromotionRedemption{PromotionId=promotionId,PatientUserId=patientUserId,Reference=(reference??"").Trim(),RecordedBy=HttpContext.Session.GetString("User")!});db.PromotionAudits.Add(new PromotionAudit{PromotionId=promotionId,Action="Redeemed",OwnerUsername=HttpContext.Session.GetString("User")!,Details=$"Patient account #{patientUserId}, reference: {reference}"});await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
 public async Task<IActionResult> Public() {var today=DateTime.Today;return View(await db.ClinicPromotions.Where(x=>x.IsPublished&&x.StartsAt<=today&&x.EndsAt>=today).OrderBy(x=>x.EndsAt).ToListAsync());}
}
